#include <format>
#include <iostream>
#include <memory>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

void in_order_into(const Node* root, std::vector<int>& out) {
  if (root == nullptr) return;  // the empty tree is the base case
  in_order_into(root->left.get(), out);
  out.push_back(root->value);
  in_order_into(root->right.get(), out);
}

[[nodiscard]] std::vector<int> in_order(const Node* root) {
  std::vector<int> out;
  in_order_into(root, out);
  return out;
}

[[nodiscard]] std::vector<int> in_order_iterative(const Node* root) {
  std::vector<int> out;
  std::vector<const Node*> pending;  // nodes whose left subtree is being walked
  const Node* current = root;
  while (current != nullptr || !pending.empty()) {
    while (current != nullptr) {  // go as far left as the tree allows
      pending.push_back(current);
      current = current->left.get();
    }
    current = pending.back();
    pending.pop_back();
    out.push_back(current->value);   // the leftmost node not yet taken
    current = current->right.get();  // then its right subtree
  }
  return out;
}

[[nodiscard]] std::string show(std::span<const int> values) {
  std::string out;
  for (const int v : values) out += std::format("{}{}", out.empty() ? "" : " ", v);
  return out.empty() ? "(empty)" : out;
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  std::cout << std::format("recursive {}\n", show(in_order(tree.get())));
  std::cout << std::format("iterative {}\n", show(in_order_iterative(tree.get())));
  std::cout << std::format("empty     {} and {}\n", show(in_order(nullptr)), show(in_order_iterative(nullptr)));
  const std::unique_ptr<Node> one = node(7);
  std::cout << std::format("one node  {} and {}\n", show(in_order(one.get())), show(in_order_iterative(one.get())));
}

