struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

void pre_order(const Node* n, std::vector<int>& out) {
  if (n == nullptr) return;
  out.push_back(n->value);  // the node, before either subtree
  pre_order(n->left.get(), out);
  pre_order(n->right.get(), out);
}

void in_order(const Node* n, std::vector<int>& out) {
  if (n == nullptr) return;
  in_order(n->left.get(), out);
  out.push_back(n->value);  // the node, between its subtrees
  in_order(n->right.get(), out);
}

void post_order(const Node* n, std::vector<int>& out) {
  if (n == nullptr) return;
  post_order(n->left.get(), out);
  post_order(n->right.get(), out);
  out.push_back(n->value);  // the node, after both subtrees
}

[[nodiscard]] std::vector<int> level_order(const Node* root) {
  std::vector<int> out;
  if (root == nullptr) return out;
  std::queue<const Node*> waiting;
  waiting.push(root);
  while (!waiting.empty()) {
    const Node* n = waiting.front();
    waiting.pop();
    out.push_back(n->value);
    if (n->left) waiting.push(n->left.get());
    if (n->right) waiting.push(n->right.get());
  }
  return out;
}

[[nodiscard]] std::string show(std::span<const int> values) {
  std::string out;
  for (const int v : values) out += std::format("{}{}", out.empty() ? "" : " ", v);
  return out;
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  std::vector<int> pre;
  pre_order(tree.get(), pre);
  std::vector<int> in;
  in_order(tree.get(), in);
  std::vector<int> post;
  post_order(tree.get(), post);
  std::cout << std::format("pre-order    {}\n", show(pre));
  std::cout << std::format("in-order     {}\n", show(in));
  std::cout << std::format("post-order   {}\n", show(post));
  std::cout << std::format("level order  {}\n", show(level_order(tree.get())));
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <memory>
#include <queue>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

enum class Order { pre, in, post };
enum class Step { descend, visit };

struct Frame {
  const Node* node = nullptr;
  Step step = Step::descend;
};

struct Walk {
  std::vector<int> values;
  std::ptrdiff_t widest = 0;  // the most entries ever waiting at once
};

// One loop for all three depth-first orders: only where `self` goes onto the stack changes.
[[nodiscard]] Walk depth_first(const Node* root, Order order) {
  Walk walk;
  std::vector<Frame> stack;
  if (root != nullptr) stack.push_back({.node = root, .step = Step::descend});
  while (!stack.empty()) {
    walk.widest = std::max(walk.widest, std::ssize(stack));
    const Frame frame = stack.back();
    stack.pop_back();
    if (frame.step == Step::visit) {
      walk.values.push_back(frame.node->value);
      continue;
    }
    const Frame self{.node = frame.node, .step = Step::visit};
    const Node* left = frame.node->left.get();
    const Node* right = frame.node->right.get();
    if (order == Order::post) stack.push_back(self);  // pushed first, so popped last
    if (right != nullptr) stack.push_back({.node = right, .step = Step::descend});
    if (order == Order::in) stack.push_back(self);
    if (left != nullptr) stack.push_back({.node = left, .step = Step::descend});
    if (order == Order::pre) stack.push_back(self);  // pushed last, so popped first
  }
  return walk;
}

[[nodiscard]] Walk breadth_first(const Node* root) {
  Walk walk;
  if (root == nullptr) return walk;
  std::queue<const Node*> waiting;
  waiting.push(root);
  while (!waiting.empty()) {
    walk.widest = std::max(walk.widest, std::ssize(waiting));
    const Node* n = waiting.front();
    waiting.pop();
    walk.values.push_back(n->value);
    if (n->left) waiting.push(n->left.get());
    if (n->right) waiting.push(n->right.get());
  }
  return walk;
}

[[nodiscard]] std::string show(std::span<const int> values) {
  std::string out;
  for (const int v : values) out += std::format("{}{}", out.empty() ? "" : " ", v);
  return out;
}

// A perfect tree of 2^(height+1) - 1 nodes, built from the leaves up so nothing recurses.
[[nodiscard]] std::unique_ptr<Node> perfect(int height) {
  std::vector<std::unique_ptr<Node>> level;
  for (std::ptrdiff_t i = 0; i < (std::ptrdiff_t{1} << height); ++i) level.push_back(node(0));
  while (std::ssize(level) > 1) {
    std::vector<std::unique_ptr<Node>> parents;
    for (std::ptrdiff_t i = 0; i < std::ssize(level); i += 2)
      parents.push_back(node(0, std::move(level[static_cast<std::size_t>(i)]),
                             std::move(level[static_cast<std::size_t>(i + 1)])));
    level = std::move(parents);
  }
  return std::move(level.front());
}

// A chain of left children, the worst shape a binary tree can have.
[[nodiscard]] std::unique_ptr<Node> leaning(std::ptrdiff_t nodes) {
  std::unique_ptr<Node> root;
  for (std::ptrdiff_t i = 0; i < nodes; ++i) root = node(0, std::move(root));
  return root;
}

void row(std::string_view shape, const Node* root, std::ptrdiff_t height) {
  const Walk depth = depth_first(root, Order::in);
  const Walk breadth = breadth_first(root);
  std::cout << std::format("{:<22}{:>7}{:>9}{:>16}{:>15}\n", shape, depth.values.size(), height, depth.widest,
                           breadth.widest);
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  std::cout << std::format("pre-order    {}\n", show(depth_first(tree.get(), Order::pre).values));
  std::cout << std::format("in-order     {}\n", show(depth_first(tree.get(), Order::in).values));
  std::cout << std::format("post-order   {}\n", show(depth_first(tree.get(), Order::post).values));
  std::cout << std::format("level order  {}\n", show(breadth_first(tree.get()).values));

  std::cout << std::format("\n{:<22}{:>7}{:>9}{:>16}{:>15}\n", "shape", "nodes", "height", "deepest stack",
                           "widest queue");
  const std::unique_ptr<Node> balanced = perfect(10);
  row("perfect, height 10", balanced.get(), 10);
  const std::unique_ptr<Node> chain = leaning(2047);
  row("2047 left children", chain.get(), 2046);
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

[[nodiscard]] std::ptrdiff_t max_depth(const Node* n) {
  if (n == nullptr) return 0;  // the empty tree has no nodes on any path
  return 1 + std::max(max_depth(n->left.get()), max_depth(n->right.get()));
}

struct Reached {
  const Node* node = nullptr;
  std::ptrdiff_t depth = 0;  // nodes from the root to this one, this one included
};

[[nodiscard]] std::ptrdiff_t max_depth_iterative(const Node* root) {
  std::ptrdiff_t deepest = 0;
  std::vector<Reached> pending;
  if (root != nullptr) pending.push_back({.node = root, .depth = 1});
  while (!pending.empty()) {
    const Reached here = pending.back();
    pending.pop_back();
    deepest = std::max(deepest, here.depth);
    if (here.node->left) pending.push_back({.node = here.node->left.get(), .depth = here.depth + 1});
    if (here.node->right) pending.push_back({.node = here.node->right.get(), .depth = here.depth + 1});
  }
  return deepest;
}

// A chain of left children, built without recursion.
[[nodiscard]] std::unique_ptr<Node> leaning(std::ptrdiff_t nodes) {
  std::unique_ptr<Node> root;
  for (std::ptrdiff_t i = 0; i < nodes; ++i) root = node(0, std::move(root));
  return root;
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  const std::unique_ptr<Node> one = node(7);
  std::cout << std::format("sample tree: {} recursive, {} iterative\n", max_depth(tree.get()),
                           max_depth_iterative(tree.get()));
  std::cout << std::format("empty tree:  {} recursive, {} iterative\n", max_depth(nullptr),
                           max_depth_iterative(nullptr));
  std::cout << std::format("one node:    {} recursive, {} iterative\n", max_depth(one.get()),
                           max_depth_iterative(one.get()));
  const std::unique_ptr<Node> chain = leaning(50'000);
  std::cout << std::format("50000 left children: {} iterative\n", max_depth_iterative(chain.get()));
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <memory>
#include <queue>
#include <ranges>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

[[nodiscard]] std::vector<std::vector<int>> levels(const Node* root) {
  std::vector<std::vector<int>> out;
  if (root == nullptr) return out;
  std::queue<const Node*> waiting;
  waiting.push(root);
  while (!waiting.empty()) {
    const std::ptrdiff_t width = std::ssize(waiting);  // the whole level, measured before it is drained
    std::vector<int> level;
    level.reserve(static_cast<std::size_t>(width));
    for (std::ptrdiff_t i = 0; i < width; ++i) {
      const Node* n = waiting.front();
      waiting.pop();
      level.push_back(n->value);
      if (n->left) waiting.push(n->left.get());
      if (n->right) waiting.push(n->right.get());
    }
    out.push_back(std::move(level));
  }
  return out;
}

[[nodiscard]] std::string show(std::span<const std::vector<int>> rows) {
  std::string out;
  for (const std::vector<int>& row : rows) {
    std::string values;
    for (const int v : row) values += std::format("{}{}", values.empty() ? "" : " ", v);
    out += std::format("{}[{}]", out.empty() ? "" : " ", values);
  }
  return out.empty() ? "(none)" : out;
}

int main() {
  const std::unique_ptr<Node> tree = node(5, node(3, node(2, node(1)), node(4)), node(8, nullptr, node(9)));
  const std::vector<std::vector<int>> rows = levels(tree.get());
  std::cout << std::format("sample  {}\n", show(rows));
  std::cout << std::format("empty   {}\n", show(levels(nullptr)));
  const std::unique_ptr<Node> one = node(7);
  std::cout << std::format("one     {}\n", show(levels(one.get())));

  std::vector<std::vector<int>> bottom_up = rows;
  std::ranges::reverse(bottom_up);
  std::cout << std::format("bottom  {}\n", show(bottom_up));

  std::string rightmost;
  for (const std::vector<int>& row : rows) rightmost += std::format("{}{}", rightmost.empty() ? "" : " ", row.back());
  const auto widest = std::ranges::max_element(rows, {}, [](const std::vector<int>& row) { return row.size(); });
  std::cout << std::format("right side {}, widest level {} nodes\n", rightmost, widest->size());
}

