#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

// Owns a tree of nodes and takes it apart one node at a time.
class Tree {
 public:
  Tree() = default;
  Tree(const Tree&) = delete;
  Tree& operator=(const Tree&) = delete;
  Tree(Tree&&) noexcept = default;
  Tree& operator=(Tree&& other) noexcept {
    clear();  // the defaulted version would destroy the old tree recursively
    root_ = std::move(other.root_);
    return *this;
  }
  ~Tree() { clear(); }

  void adopt(std::unique_ptr<Node> root) {
    clear();
    root_ = std::move(root);
  }

  // Rotates the left child up until the root has none, then drops the root and repeats.
  // Every node dies with both links already empty, so no destructor calls another.
  void clear() noexcept {
    while (root_) {
      if (root_->left) {
        std::unique_ptr<Node> left = std::move(root_->left);
        root_->left = std::move(left->right);
        left->right = std::move(root_);
        root_ = std::move(left);
      } else {
        std::unique_ptr<Node> right = std::move(root_->right);  // take the child out first
        root_ = std::move(right);                               // then drop the root, which is now a leaf
      }
    }
  }

  [[nodiscard]] const Node* root() const { return root_.get(); }

 private:
  std::unique_ptr<Node> root_;
};

struct Reached {
  const Node* node = nullptr;
  std::ptrdiff_t depth = 0;
};

[[nodiscard]] std::ptrdiff_t max_depth_iterative(const Node* root) {
  std::ptrdiff_t deepest = 0;
  std::vector<Reached> pending;
  if (root != nullptr) pending.push_back({.node = root, .depth = 1});
  while (!pending.empty()) {
    const Reached here = pending.back();
    pending.pop_back();
    deepest = std::max(deepest, here.depth);
    if (here.node->left) pending.push_back({.node = here.node->left.get(), .depth = here.depth + 1});
    if (here.node->right) pending.push_back({.node = here.node->right.get(), .depth = here.depth + 1});
  }
  return deepest;
}

[[nodiscard]] std::unique_ptr<Node> leaning(std::ptrdiff_t nodes) {
  std::unique_ptr<Node> root;
  for (std::ptrdiff_t i = 0; i < nodes; ++i) root = std::make_unique<Node>(0, std::move(root), nullptr);
  return root;
}

[[nodiscard]] std::unique_ptr<Node> perfect(int height) {
  std::vector<std::unique_ptr<Node>> level;
  for (std::ptrdiff_t i = 0; i < (std::ptrdiff_t{1} << height); ++i)
    level.push_back(std::make_unique<Node>(0, nullptr, nullptr));
  while (std::ssize(level) > 1) {
    std::vector<std::unique_ptr<Node>> parents;
    for (std::ptrdiff_t i = 0; i < std::ssize(level); i += 2)
      parents.push_back(std::make_unique<Node>(0, std::move(level[static_cast<std::size_t>(i)]),
                                               std::move(level[static_cast<std::size_t>(i + 1)])));
    level = std::move(parents);
  }
  return std::move(level.front());
}

int main() {
  Tree chain;
  chain.adopt(leaning(1'000'000));
  std::cout << std::format("chain depth {}\n", max_depth_iterative(chain.root()));
  Tree balanced;
  balanced.adopt(perfect(16));
  std::cout << std::format("perfect depth {}\n", max_depth_iterative(balanced.root()));
  chain = std::move(balanced);
  std::cout << std::format("after the move, depth {}\n", max_depth_iterative(chain.root()));
}
